/**
 * Tenant self-signup orchestrator (design doc 3.4 steps a-j, D16;
 * implementation plan W8). Invoked asynchronously by `signup-setup` with
 * `{ email, requestId }` once the setup or retry route has moved the record
 * to `provisioning`.
 *
 * Run isolation (D16): the first action is `claimRun`, which stamps this
 * delivery's `awsRequestId` on the record; every later state write is
 * fenced on both ids, and `heartbeat` runs immediately before each external
 * side effect (license create / revoke / activate, provision-tenant). A
 * fence miss, an uncertain write or a closed writer gate ends the run with
 * no further side effect; the 15-minute reclaim in `/signup/me` frees the
 * record. This Lambda never retries a side effect on its own and never
 * rolls a record back: each step failure parks the signup in its own
 * `*_pending` status (or `failed`) with a stable `lastErrorCode`, and the
 * retry / setup routes bring it back here.
 *
 * Where a run starts is decided from the record, not only from `resumeFrom`:
 *   cleanup_pending      -> verify the tenant is gone, revoke the license, `failed`
 *   tables_pending       -> provision-tenant `retry-tables`, then g-j
 *   ASM ids on record    -> g-j (provisioning already happened; a crash
 *                           between d and the first parking write resumes here
 *                           instead of hitting its own tenant at 3.4 b)
 *   own tenant at 3.4 b  -> ids recovered from its TENANT# record, then g-j
 *                           (`tables_pending` / still `provisioning` park)
 *   otherwise            -> b-j
 * Steps g, h, i are idempotent against their services, so running them
 * again on a retry is safe.
 *
 * No string from a billing, ASM or SDK reply is logged or stored: we log
 * codes and names and compose every message ourselves (W9 rule).
 *
 * Env: AMFATENANT_TABLE, ADMIN_USERPOOL_ID, PROVISION_TENANT_FUNCTION_NAME,
 * BILLING_BASE_URL, BILLING_INSTALL_URL, BILLING_SECRET_ID,
 * BILLING_PRODUCT_CODE (default AWS, D4), SIGNUP_MAX_USER_COUNT (monthly cap).
 */
import { LambdaClient, InvokeCommand } from "@aws-sdk/client-lambda";
import { CognitoIdentityProviderClient, CreateGroupCommand, AdminAddUserToGroupCommand } from "@aws-sdk/client-cognito-identity-provider";
import {
  STATUS,
  SignupStateError,
  TABLE,
  dynamodbClient,
  QueryCommand,
  UpdateItemCommand,
  normalizeEmail,
  claimRun,
  heartbeat,
  orchestratorTransition,
  fail,
} from "../shared/signup/state.mjs";
import {
  createPendingLicense,
  listLicenses,
  resolveLicenseFor409,
  activateLicense,
  revokeLicense,
  patchCustomerIds,
} from "../shared/billing/client.mjs";
import { BillingError } from "../shared/billing/errors.mjs";

/** D4: monthly bills by the cap, never a chosen seat count. Same knob as the wizard's yearly ceiling (D11). */
export const MONTHLY_SEAT_CAP = Number(process.env.SIGNUP_MAX_USER_COUNT) || 50000;
/** Q3 (2026-09-01): the platform bills by cadence; this is only the hard end. */
export const LICENSE_EXPIRATION_DATE = "2050-12-31";
export const PRODUCT_CODE = process.env.BILLING_PRODUCT_CODE || "AWS";
/** Same rule as provision-tenant/validation.mjs and setup-helpers.mjs. */
const TENANT_ID_REGEX = /^[a-z0-9]{5,36}$/;
/** Leave the Invoke this much before our own deadline so the parking write still fits. */
export const INVOKE_MARGIN_MS = 20_000;
/**
 * provision-tenant's own timeout (cdk/lib/application.ts, 15 min; the CDK
 * wiring test pins it) plus a margin. After an uncertain Invoke the target
 * may still be running for this long, so a `cleanup_pending` signup is not
 * certified clean before `cleanupNotBefore` = park time + this (codex W8
 * round 1 P1).
 */
export const PROVISION_TENANT_MAX_MS = 15 * 60_000 + 60_000;
const DDB_CALL_MS = 3_000;

// provision-tenant is not idempotent: one attempt, the outcome decides.
export const lambdaClient = new LambdaClient({ maxAttempts: 1 });
export const cognitoClient = new CognitoIdentityProviderClient({});

const log = (level, message, extra = {}) =>
  console.log(JSON.stringify({ timestamp: new Date().toISOString(), level, service: "signup-orchestrator", message, ...extra }));

/** A step failure: park the signup in `status` with this stable code. Message text is ours. */
class Park extends Error {
  constructor(status, code, message, set = {}) {
    super(message);
    this.name = "Park";
    this.status = status;
    this.code = code;
    this.set = set;
  }
}

/** Diagnostic fields safe to log for any upstream/SDK error: never its text. */
const errInfo = (err) => ({ errorName: err?.name, errorCode: err?.code, httpStatus: err?.status ?? err?.$metadata?.httpStatusCode });

const remaining = (deadlineAt) => Math.max(1_000, deadlineAt - Date.now());
const abortIn = (ms) => AbortSignal.timeout(ms);

// ---------------------------------------------------------------------------
// Record helpers
// ---------------------------------------------------------------------------

/** The saved wizard form (3.3), written by `acquire()` as a JSON string. */
export function parseForm(record) {
  let form;
  try {
    form = JSON.parse(record.form);
  } catch {
    form = null;
  }
  if (!form || typeof form !== "object" || Array.isArray(form)) throw new Park(STATUS.FAILED, "invalid_form", "The saved setup form is unreadable; run setup again.");
  if (!TENANT_ID_REGEX.test(form.tenantId || "")) throw new Park(STATUS.FAILED, "invalid_form", "The saved tenant ID is invalid; run setup again.");
  if (!["monthly", "yearly"].includes(form.billingCadence)) throw new Park(STATUS.FAILED, "invalid_form", "The saved billing cadence is invalid; run setup again.");
  if (form.billingCadence === "yearly" && !(Number.isInteger(form.userCount) && form.userCount >= 1)) throw new Park(STATUS.FAILED, "invalid_form", "The saved user count is invalid; run setup again.");
  return form;
}

/** Provisioning ids saved on the record after 3.4 d (`asmIds` JSON). */
function savedIds(record) {
  if (!record?.asmIds) return null;
  try {
    const ids = typeof record.asmIds === "string" ? JSON.parse(record.asmIds) : record.asmIds;
    return ids && typeof ids === "object" ? ids : null;
  } catch {
    return null;
  }
}

const seatsFor = (form) => (form.billingCadence === "monthly" ? MONTHLY_SEAT_CAP : form.userCount);

// ---------------------------------------------------------------------------
// TENANT# record (owned by provision-tenant; W8 only reads it and writes the
// two billing ids at completion, 3.4 b / j)
// ---------------------------------------------------------------------------

/**
 * First TENANT#<tenantId> item, or null. Query on the partition key (the sk
 * is a timestamp). Strongly consistent: absence is used as a safety
 * condition (3.4 b, cleanup verification), and a record provision-tenant
 * wrote moments ago must not read as missing (codex W8 round 1 P1).
 */
async function findTenantRecord(tenantId, deadlineAt) {
  const res = await dynamodbClient.send(
    new QueryCommand({
      TableName: TABLE,
      KeyConditionExpression: "id = :id AND begins_with(sk, :p)",
      ExpressionAttributeValues: { ":id": { S: `TENANT#${tenantId}` }, ":p": { S: "TENANT#" } },
      Limit: 1,
      ConsistentRead: true,
    }),
    { abortSignal: abortIn(Math.min(DDB_CALL_MS, remaining(deadlineAt))) },
  );
  const item = res.Items?.[0];
  if (!item) return null;
  const str = (k) => item[k]?.S ?? item[k]?.N;
  return {
    id: str("id"), sk: str("sk"), status: str("status"), orgId: str("org_id"),
    contact: str("contact"), adminEmail: str("adminEmail"),
    asmClientId: str("asmClientId"), serviceProviderId: str("serviceProviderId"), billingCustomerId: str("billingCustomerId"),
    signupReservationId: str("signupReservationId"),
  };
}

/** `cleanup_pending` parks after an uncertain provisioning call carry the earliest safe cleanup time. */
const notBefore = () => ({ cleanupNotBefore: new Date(Date.now() + PROVISION_TENANT_MAX_MS).toISOString() });

// ---------------------------------------------------------------------------
// Steps
// ---------------------------------------------------------------------------

/**
 * 3.4 b: a known conflict fails before any license is created — unless the
 * existing tenant is THIS signup's own: provision-tenant stamps the
 * signup's `reservationId` on the TENANT# record (`signupReservationId`,
 * sent in the body below), and only an exact match proves ownership (codex
 * W8 round 2 P1: org + contact email are shared by admin-created tenants
 * and would let a signup adopt one). Then an earlier run created it and
 * died before saving the ids (round 1 P1): recover the ids from the record
 * and continue at g; `tables_pending` parks for the table retry; a record
 * still `provisioning` may belong to a running invocation and is an
 * operator question. The org / email / customer checks stay as sanity
 * guards on top of the marker.
 */
async function precheckTenant(run, record, form) {
  let existing;
  try {
    existing = await findTenantRecord(form.tenantId, run.deadlineAt);
  } catch (err) {
    run.log("ERROR", "tenant uniqueness check failed", errInfo(err));
    throw new Park(STATUS.FAILED, "tenant_check_failed", "Could not verify the tenant ID is free; run setup again.");
  }
  if (!existing) return null;
  const emails = [existing.contact, existing.adminEmail].filter(Boolean).map((e) => normalizeEmail(e));
  const ours = Boolean(record.reservationId) && existing.signupReservationId === record.reservationId
    && existing.orgId === record.orgId && emails.includes(run.email)
    && (existing.billingCustomerId === undefined || String(existing.billingCustomerId) === String(record.billingCustomerId));
  if (!ours) throw new Park(STATUS.FAILED, "tenant_exists", `Tenant ID '${form.tenantId}' is already taken; choose another.`);
  run.log("WARN", "tenant from an earlier run of this signup found; recovering its ids", { tenantId: form.tenantId, tenantStatus: existing.status });
  if (existing.status === "provisioning" || !existing.asmClientId || !existing.serviceProviderId) {
    throw new Park(STATUS.CLEANUP_PENDING, "tenant_provisioning_unfinished", "An earlier provisioning of this tenant did not finish; an operator must check it before retrying.", notBefore());
  }
  const ids = { asmClientId: existing.asmClientId, serviceProviderId: existing.serviceProviderId, recordKey: { id: existing.id, sk: existing.sk } };
  if (existing.status === "tables_pending") {
    throw new Park(STATUS.TABLES_PENDING, "tables_failed", "The tenant was created but its tables were not; retry to finish.", idsAttrs(ids));
  }
  await orchestratorTransition(run.email, { requestId: run.requestId, runId: run.runId, to: STATUS.PROVISIONING, set: idsAttrs(ids), deadlineAt: run.deadlineAt });
  return ids;
}

/** The TENANT# record carries this signup's marker (and, when known, sits under the saved key). */
function isOwnTenant(existing, record, ids) {
  if (!existing || !record.reservationId || existing.signupReservationId !== record.reservationId) return false;
  return !ids?.recordKey || (existing.id === ids.recordKey.id && existing.sk === ids.recordKey.sk);
}

/**
 * A resume that starts from saved ids skips the 3.4 b pre-check, so the
 * tenant it is about to touch must be re-read: between runs an operator
 * may have deleted the parked tenant and someone else re-used its ID
 * (codex W8 round 7 P1). Without this, `retry-tables` would mutate the
 * replacement and 3.4 g would grant the signup user its TA group before
 * `complete` notices the key mismatch. A missing or foreign tenant parks
 * `cleanup_pending`, where cleanupResume revokes the license and clears
 * the ids so the user can run setup again.
 */
async function verifyOwnedTenant(run, record, form, ids) {
  let existing;
  try {
    existing = await findTenantRecord(form.tenantId, run.deadlineAt);
  } catch (err) {
    run.log("ERROR", "tenant ownership check failed", errInfo(err));
    throw new Park(record.resumeFrom || STATUS.FAILED, "tenant_check_failed", "Could not verify the tenant before resuming; retry.");
  }
  if (isOwnTenant(existing, record, ids)) return;
  run.log("ERROR", "saved tenant ids no longer describe this signup's tenant", { tenantId: form.tenantId, found: Boolean(existing) });
  throw new Park(STATUS.CLEANUP_PENDING, existing ? "tenant_replaced" : "tenant_missing", `Tenant '${form.tenantId}' is no longer this signup's; an operator must check it before retrying.`);
}

/** License ids the customer held before this signup's first create (`licenseIdsBefore` JSON), or null if never snapshotted. */
function licenseIdsBefore(record) {
  if (record?.licenseIdsBefore === undefined || record?.licenseIdsBefore === null) return null;
  try {
    const ids = typeof record.licenseIdsBefore === "string" ? JSON.parse(record.licenseIdsBefore) : record.licenseIdsBefore;
    return Array.isArray(ids) ? ids.map(String) : null;
  } catch {
    return null;
  }
}

/**
 * A 409 license is this signup's when its id is the one a prior run of THIS
 * signup saved at 3.4 c, or when it is absent from the snapshot of the
 * customer's licenses taken right before this signup's first create: a
 * license that did not exist then is the one our POST committed while its
 * response was lost (client timeout retry, or a crash before the 3.4 c
 * save; codex W8 round 9 P1). licdev's 409 returns the customer's existing
 * license whoever the caller is, so without either proof a customer who
 * already holds a live license would have it "reused", sent to ASM (403 key
 * already used) and then revoked by 3.4 f. The dev run of 2026-10-08 did
 * exactly that to license 25014 (D2 amendment; see the implementation doc).
 */
function ownsLicense(record, licenseId) {
  if (licenseId === undefined || licenseId === null) return false;
  if (record.licenseId !== undefined && record.licenseId !== null) return String(licenseId) === String(record.licenseId);
  const before = licenseIdsBefore(record);
  return before !== null && !before.includes(String(licenseId));
}

/**
 * Snapshot the customer's existing license ids once per signup, before the
 * first create, so a later 409 can be attributed (see ownsLicense). Taken
 * only when neither a saved id nor a snapshot exists: re-listing on a resume
 * would record our own orphan as pre-existing. ponytail: a foreign license
 * created in the seconds between this snapshot and our POST would be
 * adopted; licdev exposes no created_at to close that window.
 */
async function snapshotLicenses(run, record) {
  if ((record.licenseId !== undefined && record.licenseId !== null) || licenseIdsBefore(record) !== null) return record;
  let ids;
  try {
    const list = await listLicenses({ customerId: record.billingCustomerId, productCode: PRODUCT_CODE });
    if (!Array.isArray(list)) throw new BillingError("bad_response", 502, { detail: "list_licenses did not return an array" });
    ids = list.map((l) => String(l?.id)).filter((id) => id !== "undefined" && id !== "null");
  } catch (err) {
    if (err instanceof SignupStateError) throw err;
    run.log("ERROR", "license snapshot failed", errInfo(err));
    throw new Park(STATUS.FAILED, "license_precheck_failed", "Checking the billing platform failed; try again.");
  }
  const licenseIdsBeforeJson = JSON.stringify(ids);
  await orchestratorTransition(run.email, { requestId: run.requestId, runId: run.runId, to: STATUS.PROVISIONING, set: { licenseIdsBefore: licenseIdsBeforeJson }, deadlineAt: run.deadlineAt });
  run.log("INFO", "license snapshot saved", { count: ids.length });
  return { ...record, licenseIdsBefore: licenseIdsBeforeJson };
}

/** 3.4 c: pending license; 409 resolved per D2 for OUR license only. Persists the ids before provisioning. */
async function ensureLicense(run, record, form) {
  const seats = seatsFor(form);
  const selection = { billingCadence: form.billingCadence, seats, discountCode: form.promoCode };
  const create = () =>
    createPendingLicense({ customerId: record.billingCustomerId, productCode: PRODUCT_CODE, ...selection, expirationDate: LICENSE_EXPIRATION_DATE });
  let license;
  let created;
  record = await snapshotLicenses(run, record);
  try {
    await heartbeat(run.email, run.requestId, run.runId, { deadlineAt: run.deadlineAt });
    let res = await create();
    created = res.created;
    if (!res.created) {
      if (!ownsLicense(record, res.license?.id)) {
        // Not ours: never reuse, never revoke. An operator links or replaces it.
        run.log("ERROR", "existing license returned on create is not this signup's", { licenseId: res.license?.id, licenseStatus: res.license?.status, savedLicenseId: record.licenseId ?? null, snapshotted: licenseIdsBefore(record) !== null });
        throw new Park(STATUS.FAILED, "license_conflict", "This customer already has a license on the billing platform; contact support to link or replace it before retrying.");
      }
      // Ours by the pre-create snapshot (no saved id yet): our POST committed
      // and only its response was lost, so for revoke purposes this run
      // created it. Ours by saved id: a resume, created stays false.
      const adopted = record.licenseId === undefined || record.licenseId === null;
      if (adopted && res.license.status !== "pending") {
        // A license we created but never saved can only be pending (activation
        // is 3.4 i, after the save); anything else arrived from elsewhere.
        run.log("ERROR", "unsaved license from the snapshot window is not pending; not ours", { licenseId: res.license.id, licenseStatus: res.license.status });
        throw new Park(STATUS.FAILED, "license_conflict", "This customer already has a license on the billing platform; contact support to link or replace it before retrying.");
      }
      created = adopted;
      const decision = resolveLicenseFor409(res.license, selection);
      // 3.4 c: log the mismatch for CRM correction; the ids are what matters.
      run.log(decision.mismatch ? "WARN" : "INFO", "existing license returned on create", { action: decision.action, mismatch: decision.mismatch, licenseId: res.license.id, licenseStatus: res.license.status, adopted });
      if (decision.action === "fail") {
        throw new Park(STATUS.FAILED, "license_conflict", "An existing license for this customer is in a state we cannot reuse; contact support.");
      }
      if (decision.action === "recreate") {
        await heartbeat(run.email, run.requestId, run.runId, { deadlineAt: run.deadlineAt });
        await revokeLicense(res.license.id);
        await heartbeat(run.email, run.requestId, run.runId, { deadlineAt: run.deadlineAt });
        res = await create();
        // The replacement is ours whether the POST answered 201 or its retry
        // saw it as a 409: the only license the customer held a moment ago
        // was the one we just revoked.
        created = true;
        if (!res.created) {
          // The replacement POST can commit while its response is lost; the
          // client's retry then returns the new pending license as a 409. A
          // matching pending license is ours to reuse; anything else is a
          // real conflict (round 7 P2).
          const again = resolveLicenseFor409(res.license, selection);
          run.log(again.action === "reuse" ? "INFO" : "WARN", "existing license returned after recreate", { action: again.action, mismatch: again.mismatch, licenseId: res.license.id, licenseStatus: res.license.status });
          if (again.action !== "reuse") throw new Park(STATUS.FAILED, "license_conflict", "The billing platform still reports a conflicting license; try again.");
        }
      }
    }
    license = res.license;
  } catch (err) {
    if (err instanceof Park || err instanceof SignupStateError) throw err;
    run.log("ERROR", "license creation failed", errInfo(err));
    // A BillingError carries our own table text (errors.mjs), which says
    // why (bad promo, record not found, platform down) instead of a blanket
    // "try again" that is wrong for the non-retryable codes.
    throw new Park(STATUS.FAILED, `license_${err?.code || "create_failed"}`, err?.userMessage || "Creating the license failed; try again.");
  }
  if (!license?.id || !license?.license_key) throw new Park(STATUS.FAILED, "license_response_invalid", "The billing platform returned an incomplete license; try again.");
  await orchestratorTransition(run.email, {
    requestId: run.requestId, runId: run.runId, to: STATUS.PROVISIONING,
    set: { licenseId: license.id, licenseKey: license.license_key, tenantId: form.tenantId, tenantName: form.tenantName, billingCadence: form.billingCadence, seats, discountCode: form.promoCode },
    deadlineAt: run.deadlineAt,
  });
  run.log("INFO", "license ready", { licenseId: license.id, created });
  return { licenseId: license.id, licenseKey: license.license_key, created };
}

/** Decode a RequestResponse Invoke of provision-tenant into `{ statusCode, body }` or null. */
export function decodeInvokeResult(res) {
  try {
    const api = JSON.parse(Buffer.from(res.Payload).toString("utf8"));
    const body = typeof api?.body === "string" ? JSON.parse(api.body) : api?.body;
    if (!Number.isInteger(api?.statusCode) || !body || typeof body !== "object") return null;
    return { statusCode: api.statusCode, body };
  } catch {
    return null;
  }
}

/** The ids 3.1 item 9 / round 19 promise on every 200/207 `data`. */
function idsFrom(body) {
  const d = body?.data;
  const key = d?.recordKey;
  // All three are required: 3.4 h backfills asm_tenant_id AND provider_id (round 1 P2).
  if (!d?.asmClientId || d?.serviceProviderId === undefined || d?.serviceProviderId === null || d?.serviceProviderId === "" || !key?.id || !key?.sk) return null;
  return { asmClientId: String(d.asmClientId), serviceProviderId: String(d.serviceProviderId), recordKey: { id: String(key.id), sk: String(key.sk) } };
}

const idsAttrs = (ids) => ({ asmClientId: ids.asmClientId, serviceProviderId: ids.serviceProviderId, asmIds: ids });

async function invokeProvisionTenant(run, payload, failStatus) {
  let res;
  try {
    await heartbeat(run.email, run.requestId, run.runId, { deadlineAt: run.deadlineAt });
    res = await lambdaClient.send(
      new InvokeCommand({ FunctionName: process.env.PROVISION_TENANT_FUNCTION_NAME, InvocationType: "RequestResponse", Payload: JSON.stringify(payload) }),
      { abortSignal: abortIn(Math.max(1_000, remaining(run.deadlineAt) - INVOKE_MARGIN_MS)) },
    );
  } catch (err) {
    if (err instanceof SignupStateError) throw err;
    // Transport error, abort, 4xx/5xx from the Invoke API: we do not know
    // whether the tenant exists. Never assume it does not (round 18).
    run.log("ERROR", "provision-tenant invoke failed", errInfo(err));
    // The target may still be running (the response was lost, not the
    // call): cleanup may not be certified before it can have finished.
    throw new Park(failStatus, "provision_invoke_failed", "Tenant provisioning did not answer; an operator must check for leftovers before retrying.", notBefore());
  }
  if (res.FunctionError) {
    run.log("ERROR", "provision-tenant crashed", { functionError: res.FunctionError });
    throw new Park(failStatus, "provision_crashed", "Tenant provisioning crashed; an operator must check for leftovers before retrying.", notBefore());
  }
  const api = decodeInvokeResult(res);
  if (!api) {
    run.log("ERROR", "provision-tenant returned an undecodable payload");
    throw new Park(failStatus, "provision_response_invalid", "Tenant provisioning returned an unreadable result; an operator must check for leftovers before retrying.", notBefore());
  }
  return api;
}

/** 3.4 d-f: provision the tenant with the pending key; park by outcome. */
async function provisionTenant(run, record, form, lic) {
  const api = await invokeProvisionTenant(run, {
    body: { tenantId: form.tenantId, tenantName: form.tenantName, orgId: record.orgId, contactEmail: run.email, adminEmail: run.email, samlproxy: true, licenseKey: lic.licenseKey, signupReservationId: record.reservationId },
  }, STATUS.CLEANUP_PENDING);
  const { statusCode, body } = api;

  if (statusCode === 200 || statusCode === 207) {
    const ids = idsFrom(body);
    if (!ids) {
      run.log("ERROR", "provision-tenant success without ids", { statusCode });
      throw new Park(STATUS.CLEANUP_PENDING, "provision_response_invalid", "Tenant provisioning did not return the tenant ids; an operator must check the tenant before retrying.");
    }
    if (statusCode === 207) {
      // 3.4 e: tenant exists, tables failed. Keep the license and the ids.
      throw new Park(STATUS.TABLES_PENDING, "tables_failed", "The tenant was created but its tables were not; retry to finish.", idsAttrs(ids));
    }
    await orchestratorTransition(run.email, { requestId: run.requestId, runId: run.runId, to: STATUS.PROVISIONING, set: idsAttrs(ids), deadlineAt: run.deadlineAt });
    run.log("INFO", "tenant provisioned", { tenantId: form.tenantId, asmClientId: ids.asmClientId });
    return ids;
  }

  const code = typeof body.errorCode === "string" && body.errorCode.trim() ? body.errorCode : "provision_failed";
  const rollbackPerformed = body.rollbackPerformed === true;
  run.log("ERROR", "provision-tenant failed", { statusCode, errorCode: code, rollbackPerformed });
  if (!rollbackPerformed) {
    throw new Park(STATUS.CLEANUP_PENDING, code, "Tenant provisioning failed and its rollback is not confirmed; an operator must remove leftovers before retrying.");
  }
  // 3.4 f: rollback confirmed -> revoke the pending license so the
  // customer+product pair is free and the next setup creates a fresh key
  // (an `asm_license_key_used` key must never be sent to ASM again).
  await revokeAndClearLicense(run, record, lic);
  const message =
    code === "tenant_exists" ? `Tenant ID '${form.tenantId}' is already taken; choose another.`
    : code === "validation_error" ? "Tenant provisioning rejected the setup data; run setup again."
    : "Tenant provisioning failed and was rolled back; run setup again.";
  throw new Park(STATUS.FAILED, code, message);
}

/**
 * Revoke the license and drop its ids from the record; a failed revoke parks
 * in cleanup_pending. Only a license this run created or a prior run of this
 * signup saved may be revoked (D2 amendment): the 409 gate in ensureLicense
 * makes any other id unreachable here, so the check is an invariant guard.
 */
async function revokeAndClearLicense(run, record, lic) {
  const licenseId = lic?.licenseId;
  if (licenseId === undefined || licenseId === null) return;
  if (lic.created !== true && !ownsLicense(record, licenseId)) {
    run.log("ERROR", "refusing to revoke a license this signup did not create", { licenseId, savedLicenseId: record.licenseId ?? null });
    throw new Park(STATUS.CLEANUP_PENDING, "license_not_ours", "The license in use was not created by this signup; an operator must check billing before retrying.");
  }
  try {
    await heartbeat(run.email, run.requestId, run.runId, { deadlineAt: run.deadlineAt });
    await revokeLicense(licenseId);
  } catch (err) {
    if (err instanceof SignupStateError) throw err;
    run.log("ERROR", "license revoke failed", { licenseId, ...errInfo(err) });
    throw new Park(STATUS.CLEANUP_PENDING, "license_revoke_failed", "The license could not be revoked after a failed provisioning; an operator must revoke it before retrying.");
  }
  // The snapshot goes with the license: the next create starts a new signup
  // attempt and must snapshot again (the revoked id is then pre-existing).
  await orchestratorTransition(run.email, { requestId: run.requestId, runId: run.runId, to: STATUS.PROVISIONING, remove: ["licenseId", "licenseKey", "licenseIdsBefore"], deadlineAt: run.deadlineAt });
  run.log("INFO", "license revoked", { licenseId });
}

/** 3.4 e retry: finish the tables of a tenant parked in `tables_pending`. */
async function retryTables(run, record, form) {
  const api = await invokeProvisionTenant(run, { action: "retry-tables", body: { tenantId: form.tenantId } }, STATUS.TABLES_PENDING);
  if (api.statusCode === 200) {
    const ids = idsFrom(api.body) || savedIds(record);
    if (!ids) throw new Park(STATUS.TABLES_PENDING, "provision_response_invalid", "Table recovery did not return the tenant ids; retry.");
    if (!record.asmIds) await orchestratorTransition(run.email, { requestId: run.requestId, runId: run.runId, to: STATUS.PROVISIONING, set: idsAttrs(ids), deadlineAt: run.deadlineAt });
    run.log("INFO", "tenant tables recovered", { tenantId: form.tenantId });
    return ids;
  }
  const code = api.statusCode === 207 ? "tables_failed" : (typeof api.body.errorCode === "string" && api.body.errorCode) || "retry_tables_failed";
  run.log("ERROR", "retry-tables did not complete", { statusCode: api.statusCode, errorCode: code });
  // 404 / 409 from retry-tables mean the TENANT# record is not what this
  // signup expects; that is an operator question, not another retry.
  const status = api.statusCode === 207 ? STATUS.TABLES_PENDING : STATUS.CLEANUP_PENDING;
  throw new Park(status, code, status === STATUS.TABLES_PENDING ? "The tenant tables still could not be created; retry later." : "The tenant record is not awaiting tables; an operator must check it.");
}

/** 3.4 g: TA_<tenantId> group with the invited user in it. Idempotent. */
async function assignGroup(run, form) {
  const GroupName = `TA_${form.tenantId}`;
  const UserPoolId = process.env.ADMIN_USERPOOL_ID;
  try {
    try {
      await cognitoClient.send(new CreateGroupCommand({ UserPoolId, GroupName }));
    } catch (err) {
      if (err?.name !== "GroupExistsException") throw err;
    }
    await cognitoClient.send(new AdminAddUserToGroupCommand({ UserPoolId, GroupName, Username: run.email }));
  } catch (err) {
    run.log("ERROR", "group assignment failed", { group: GroupName, ...errInfo(err) });
    throw new Park(STATUS.ROLE_ASSIGNMENT_PENDING, "group_assignment_failed", "The tenant admin role could not be assigned; retry.");
  }
}

/** 3.4 h: backfill the provisioning ids on the billing customer. Idempotent PATCH. */
async function backfillBilling(run, record, form, ids) {
  try {
    await patchCustomerIds(record.billingCustomerId, { asmTenantId: ids.asmClientId, awsTenantId: form.tenantId, providerId: ids.serviceProviderId });
  } catch (err) {
    run.log("ERROR", "billing backfill failed", errInfo(err));
    throw new Park(STATUS.BILLING_BACKFILL_PENDING, `billing_${err?.code || "backfill_failed"}`, "Billing could not be updated with the tenant ids; retry.");
  }
}

/** 3.4 i: `{ status: "active" }` and nothing else (Q21); monthly must come back with a non-zero cap. */
async function activate(run, form, lic) {
  let license;
  try {
    await heartbeat(run.email, run.requestId, run.runId, { deadlineAt: run.deadlineAt });
    license = await activateLicense(lic.licenseId);
  } catch (err) {
    if (err instanceof SignupStateError) throw err;
    run.log("ERROR", "license activation failed", { licenseId: lic.licenseId, ...errInfo(err) });
    throw new Park(STATUS.LICENSE_ACTIVATION_PENDING, `license_${err?.code || "activate_failed"}`, "The license could not be activated; retry.");
  }
  if (form.billingCadence === "monthly") {
    // The cap must come back as a positive integer: 0, missing or garbage
    // all mean ASM would be told ALLOWED_USERS 0 (3.4 i; round 1 P2).
    const cap = license?.allowed_users;
    if (!(Number.isInteger(cap) && cap > 0)) {
      run.log("ERROR", "monthly license activated without a usable cap", { licenseId: lic.licenseId, allowedUsersType: typeof cap });
      throw new Park(STATUS.LICENSE_ACTIVATION_PENDING, "allowed_users_invalid", "The license activated without a user cap; retry so the cap is set.");
    }
  }
}

/** 3.4 j: billing ids onto the TENANT# record, then `complete`. */
async function complete(run, record, form, ids, lic) {
  let key = ids.recordKey;
  try {
    if (!key) {
      // Pre-round-19 record without a saved key: the Query fallback.
      const found = await findTenantRecord(form.tenantId, run.deadlineAt);
      if (!found) throw Object.assign(new Error("tenant record missing"), { name: "TenantRecordMissing" });
      key = { id: found.id, sk: found.sk };
    }
    await dynamodbClient.send(
      new UpdateItemCommand({
        TableName: TABLE,
        Key: { id: { S: key.id }, sk: { S: key.sk } },
        ConditionExpression: "attribute_exists(id) AND (attribute_not_exists(#c) OR #c = :c)",
        UpdateExpression: "SET #c = :c, #l = :l, #u = :now",
        ExpressionAttributeNames: { "#c": "billingCustomerId", "#l": "licenseId", "#u": "updated_at" },
        ExpressionAttributeValues: { ":c": { N: String(record.billingCustomerId) }, ":l": { N: String(lic.licenseId) }, ":now": { S: new Date().toISOString() } },
      }),
      { abortSignal: abortIn(Math.min(DDB_CALL_MS, remaining(run.deadlineAt))) },
    );
  } catch (err) {
    run.log("ERROR", "tenant record update failed", { key, ...errInfo(err) });
    if (err?.name === "ConditionalCheckFailedException" || err?.name === "TenantRecordMissing") {
      throw new Park(STATUS.CLEANUP_PENDING, "tenant_record_conflict", "The tenant record belongs to another customer or is missing; an operator must check it.");
    }
    // Transient: steps g-i are idempotent, so the activation retry redoes them and lands here again.
    throw new Park(STATUS.LICENSE_ACTIVATION_PENDING, "tenant_record_update_failed", "Recording the billing ids on the tenant failed; retry.");
  }
  await orchestratorTransition(run.email, { requestId: run.requestId, runId: run.runId, to: STATUS.COMPLETE, set: { completedAt: new Date().toISOString() }, deadlineAt: run.deadlineAt });
  run.log("INFO", "signup complete", { tenantId: form.tenantId, licenseId: lic.licenseId });
}

/**
 * Resume from `cleanup_pending`: the operator says the leftovers are gone.
 * Verify (no TENANT# record), revoke the license, and land in `failed` so
 * the user runs setup again with a fresh form and a fresh key. A tenant
 * record still present means the cleanup is not done.
 */
async function cleanupResume(run, record, form) {
  const notBeforeAt = Date.parse(record.cleanupNotBefore || "");
  if (Number.isFinite(notBeforeAt) && notBeforeAt > Date.now()) {
    // An uncertain provision-tenant call may still be running; a tenant it
    // creates after this check would be left with a revoked key (round 1 P1).
    throw new Park(STATUS.CLEANUP_PENDING, "cleanup_too_early", `A provisioning call may still be running; retry after ${new Date(notBeforeAt).toISOString()}.`);
  }
  let existing;
  try {
    existing = await findTenantRecord(form.tenantId, run.deadlineAt);
  } catch (err) {
    run.log("ERROR", "cleanup verification failed", errInfo(err));
    throw new Park(STATUS.CLEANUP_PENDING, "tenant_check_failed", "Could not verify the tenant was removed; retry.");
  }
  // Our leftover: the operator has to remove it. A record under the same
  // ID WITHOUT our marker is someone else's replacement tenant (round 7
  // P1): ours is gone, so fall through and release the license and ids.
  if (existing && isOwnTenant(existing, record, savedIds(record))) {
    throw new Park(STATUS.CLEANUP_PENDING, "cleanup_incomplete", `Tenant '${form.tenantId}' still exists; remove it before retrying.`);
  }
  if (existing) run.log("WARN", "a tenant that is not this signup's now holds the ID; releasing this signup's license", { tenantId: form.tenantId });
  await revokeAndClearLicense(run, record, { licenseId: record.licenseId });
  // The tenant is gone, so the ids saved after 3.4 d describe nothing. A
  // later setup acquires the record with them intact and would skip
  // provisioning straight into `license_missing` (round 6 P1).
  await orchestratorTransition(run.email, { requestId: run.requestId, runId: run.runId, to: STATUS.PROVISIONING, remove: ["asmClientId", "serviceProviderId", "asmIds", "cleanupNotBefore"], deadlineAt: run.deadlineAt });
  throw new Park(STATUS.FAILED, "cleanup_verified", existing
    ? `Tenant ID '${form.tenantId}' is now taken by another tenant; the license was revoked. Run setup again with a different tenant ID.`
    : "Leftovers removed and the license revoked; run setup again.");
}

// ---------------------------------------------------------------------------
// Handler
// ---------------------------------------------------------------------------

async function runSteps(run, record) {
  const form = parseForm(record);
  if (record.resumeFrom === STATUS.CLEANUP_PENDING) return cleanupResume(run, record, form);

  let ids = savedIds(record);
  let lic = { licenseId: record.licenseId, licenseKey: record.licenseKey };
  if (record.resumeFrom === STATUS.TABLES_PENDING) {
    await verifyOwnedTenant(run, record, form, ids);
    ids = await retryTables(run, record, form);
  } else if (!ids) {
    ids = await precheckTenant(run, record, form);
    if (!ids) {
      lic = await ensureLicense(run, record, form);
      ids = await provisionTenant(run, record, form, lic);
    }
  } else {
    await verifyOwnedTenant(run, record, form, ids);
  }
  if (lic.licenseId === undefined || lic.licenseId === null) {
    throw new Park(STATUS.CLEANUP_PENDING, "license_missing", "The tenant exists but no license is recorded for it; an operator must check billing.");
  }
  await assignGroup(run, form);
  await backfillBilling(run, record, form, ids);
  await activate(run, form, lic);
  await complete(run, record, form, ids, lic);
  return "complete";
}

export async function handler(event, context) {
  const email = typeof event?.email === "string" && event.email.trim() ? normalizeEmail(event.email) : "";
  const requestId = typeof event?.requestId === "string" ? event.requestId.trim() : "";
  const runId = context?.awsRequestId;
  if (!email || !requestId || !runId) {
    log("ERROR", "invalid event", { hasEmail: Boolean(email), hasRequestId: Boolean(requestId), hasRunId: Boolean(runId) });
    return { exit: "invalid_event" };
  }
  const deadlineAt = Date.now() + (typeof context?.getRemainingTimeInMillis === "function" ? context.getRemainingTimeInMillis() : 60_000) - 2_000;
  const run = { email, requestId, runId, deadlineAt, log: (level, message, extra = {}) => log(level, message, { requestId, runId, ...extra }) };

  let record;
  try {
    record = await claimRun(email, requestId, runId, { deadlineAt });
  } catch (err) {
    // Duplicate delivery, superseded run, unreadable record, gate closed:
    // exit with no side effect (D16; the reclaim frees a dead claim).
    run.log("WARN", "claim refused; exiting", errInfo(err));
    return { exit: "claim_refused", code: err?.code };
  }
  run.log("INFO", "run claimed", { resumeFrom: record.resumeFrom });

  try {
    return { exit: await runSteps(run, record) };
  } catch (err) {
    if (err instanceof SignupStateError) {
      // invalid_state / write_outcome_unknown / writes_closed / budget:
      // the record is no longer ours or its state is uncertain. Stop.
      run.log("WARN", "state write refused; exiting without further side effects", errInfo(err));
      return { exit: "state_error", code: err.code };
    }
    const park = err instanceof Park ? err : new Park(STATUS.CLEANUP_PENDING, "unexpected_error", "An unexpected error interrupted provisioning; an operator must check for leftovers before retrying.", notBefore());
    if (!(err instanceof Park)) run.log("ERROR", "unexpected error", { errorName: err?.name });
    try {
      await fail(email, park.status, park, park.set, { requestId, runId, deadlineAt });
      run.log("WARN", "signup parked", { status: park.status, code: park.code });
      return { exit: "parked", status: park.status, code: park.code };
    } catch (werr) {
      run.log("ERROR", "could not park the signup; exiting", { status: park.status, code: park.code, ...errInfo(werr) });
      return { exit: "state_error", code: werr?.code };
    }
  }
}
